mapper.sql:
where r.assess_date >= #{from} and r.assess_date <= #{to}
  and r.status in #{s}
  and (r.ra_no like #{keyword} escape '\' or r.title ilike #{keyword} escape '\')

mapper.select:
select 
  from cms_risk_assess r left join cms_risk_assess pr on pr.ra_id = r.prev_ra_id
 where r.ra_id = #{id}

mapper.update:
update cms_risk_assess
   set plant_cd = #{r.plantCd}, ra_type = #{r.raType}, title = #{r.title}, scope_text = #{r.scopeText},
       assess_date = #{r.assessDate}, remark = #{r.remark}, row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where ra_id = #{r.raId} and row_ver = #{r.rowVer}

update cms_risk_assess
   set status = #{status}, apr_id = #{aprId},
       released_at = now(), released_by = #{by},
       row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where ra_id = #{id} and row_ver = #{rowVer}

update cms_risk_item
   set seq = #{i.seq}, task_text = #{i.taskText}, equip_id = #{i.equipId}, hazard_cat = #{i.hazardCat}, hazard_text = #{i.hazardText},
       current_measure = #{i.currentMeasure}, likelihood = #{i.likelihood}, severity = #{i.severity}, risk_level = #{i.riskLevel},
       plan_measure = #{i.planMeasure}, owner_user_id = #{i.ownerUserId}, due_date = #{i.dueDate},
       row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where ra_id = #{raId} and item_id = #{i.itemId} and row_ver = #{i.rowVer}

update cms_risk_item
   set done_date = #{i.doneDate}, residual_l = #{i.residualL}, residual_s = #{i.residualS}, residual_level = #{i.residualLevel},
       row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where ra_id = #{raId} and item_id = #{i.itemId} and row_ver = #{i.rowVer}

update cms_risk_member
   set notified_on = #{notifiedOn}, row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where ra_id = #{raId} and member_id = #{memberId} and row_ver = #{rowVer}
